const origin='https://checkout.staging.withflintpay.com',url=`${origin}/gift-card-challenge/gccf_fixture.token`,code='GIFTCODE-fixture-private',proof='gccp_fixtureProofOnlyOnce1234567890';
function refusal(code='GIFT_CARD_CHALLENGE_REQUIRED',reason='proof_required',status=400,challengeUrl=url){return new SdkError(status>=500?'server':'validation','fixture refusal','response',status>=500,{status,headers:{},attempts:1,durationMs:1},code,{reason,remediation:{next_actions:[{action_type:'complete_gift_card_challenge',url:challengeUrl}]}});}
function fixture(){
 const dir=mkdtempSync(join(tmpdir(),'gift-challenge-backend-')),store=new Store(join(dir,'app.sqlite')),config=readConfig({FLINT_API_KEY:'flint_test_FIXTURE',FLINT_API_BASE_URL:'https://api.staging.withflintpay.com',APP_ORIGIN:'http://localhost:4100',PORT:'4100'});
 const money={amount:'1000',currency:'USD'},zero={amount:'0',currency:'USD'},pricing={subtotal_money:money,discount_money:zero,charge_money:zero,requested_tip_money:zero,tax_money:zero,total_money:money};
 const order={order_id:'ord_fixture',order_number:'FIXTURE',status:'open',payment_status:'unpaid',order_revision:'5',gift_card_tender_enabled:true,line_items:[],pricing_amounts:pricing,settlement_amounts:{outstanding_money:money,paid_money:zero,refunded_money:zero},payment_collection:{stripe:{elements:{}}},gift_cards:[]} as unknown as Order;
 const session={checkout_session_id:'cs_fixture',status:'open',recovery_mode:false,page_origin:config.appOrigin,gift_card_challenge:{url}};
 const calls:{body:Record<string,unknown>;options:RequestOptions}[]=[],reads:RequestOptions[]=[];
 let send:()=>Promise<Order>=async()=>{throw refusal();};
 const client={orders:{get:async(_id:string,_params:unknown,options:RequestOptions)=>{reads.push(options);return order;},applyGiftCard:async(_id:string,body:Record<string,unknown>,options:RequestOptions)=>{calls.push({body:{...body},options});return send();},removeGiftCard:async()=>order},paymentMethods:{list:async()=>({data:[]})},checkoutSessions:{get:async(_id:string,_params:unknown,options:RequestOptions)=>{reads.push(options);return session;},create:async(body:Record<string,unknown>)=>({checkout_session:{...session,order_id:order.order_id,page_origin:body.page_origin},checkout_access:{checkout_auth_token:'fixture checkout authority'}})}} as unknown as Client;
 store.run('INSERT INTO payment_checkouts(checkout_ref,user_id,sandbox_id,resource_type,resource_id,order_id,checkout_session_id,checkout_auth_token,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)','chk_fixture','usr_fixture','sandbox_fixture','invoice','inv_fixture',order.order_id,session.checkout_session_id,'fixture checkout authority',Date.now(),Date.now());
 const record=store.checkout('usr_fixture','sandbox_fixture','invoice','inv_fixture')!,app=new PaymentEngine(client,createAuth(config.apiKey),store,async()=>{});
 const apply=(nonce='action-fixture')=>app.applyGift(record.checkout_ref,code,origin,nonce),retry=(id:string,giftCode=code)=>app.retryGift(record.checkout_ref,id,giftCode,proof,origin),remove=(id:string)=>app.removeGift(record.checkout_ref,id,'remove-fixture');
 return {dir,store,order,session,calls,reads,app,record,client,config,send(fn:()=>Promise<Order>){send=fn;},apply,retry,remove,close(){this.store.close();rmSync(dir,{recursive:true,force:true});}};
}
async function use(fn:(f:ReturnType<typeof fixture>)=>Promise<void>){const f=fixture();try{await fn(f);}finally{f.close();}}
const row=(f:ReturnType<typeof fixture>)=>f.store.get<{status:string;body:string;idempotency_key:string;action_id:string;result?:string}>('SELECT * FROM actions WHERE kind=\'gift_apply\' ORDER BY created_at DESC LIMIT 1')!;
const challenged=async(f:ReturnType<typeof fixture>)=>{const view=await f.apply();assert.ok(view);return view;};
async function retryRefused(f:ReturnType<typeof fixture>,id:string,expected:string,remoteReads:boolean,giftCode=code){
 const reads=f.reads.length,calls=f.calls.length;await assert.rejects(()=>f.retry(id,giftCode),{code:expected});assert.equal(f.calls.length,calls);assert.equal(f.store.get<{status:string}>('SELECT status FROM gift_challenges WHERE challenge_id=?',id)?.status,'closed');if(remoteReads)assert.ok(f.reads.length>reads);else assert.equal(f.reads.length,reads);
}
function openAttempt(f:ReturnType<typeof fixture>,source:'active'|'remembered'){
 const attempt={order_payment_attempt_id:'attempt_fixture',status:'processing',mode:'payment'};
 if(source==='active')f.order.active_payment_attempt=attempt as Order['active_payment_attempt'];else{f.store.run('UPDATE payment_checkouts SET last_attempt_id=? WHERE checkout_ref=?',attempt.order_payment_attempt_id,f.record.checkout_ref);Object.assign(f.client.orders,{getPaymentAttempt:async(_order:string,_attempt:string,_params:unknown,options:RequestOptions)=>{f.reads.push(options);return attempt;}});}
}
function localPayment(f:ReturnType<typeof fixture>,status='pending'){f.store.run('INSERT INTO actions(action_id,resource,kind,idempotency_key,body,body_hash,status,created_at) VALUES(?,?,?,?,?,?,?,?)','pay_fixture',f.app.resource(f.record),'pay','pay_fixture','{}','fixture',status,Date.now());}
function remoteGiftFence(f:ReturnType<typeof fixture>,state:'closed'|'recovery'|'disabled'|'paid'){
 if(state==='closed')f.session.status='closed';else if(state==='recovery')f.session.recovery_mode=true;else if(state==='disabled')f.order.gift_card_tender_enabled=false;else f.order.settlement_amounts.paid_money={amount:'1',currency:'USD'};
}
test('I2 challenge issuance exposes only its view and keeps a safe bound journal',async()=>use(async f=>{
 const view=await challenged(f);assert.deepEqual(Object.keys(view).sort(),['challenge_id','expires_in_seconds','reason','session_tag','url']);assert.equal(view.url,url);assert.equal(row(f).status,'challenge');assert.equal(f.store.all("SELECT * FROM gift_challenges WHERE status='open'").length,1);assert.ok(f.reads.some(read=>read.authMode==='checkout'));assert.equal(row(f).body.includes(code),false);
 for(const name of readdirSync(f.dir))assert.equal(readFileSync(join(f.dir,name)).includes(Buffer.from(url)),false);
}));
test('I3 I4 I16 retry spends the proof once with the original checkout key and revision',async()=>use(async f=>{
 const view=await challenged(f),key=row(f).idempotency_key;f.send(async()=>f.order);
 await Promise.allSettled([f.retry(view.challenge_id),f.retry(view.challenge_id)]).then(results=>{assert.equal(results.filter(r=>r.status==='fulfilled').length,1);const failed=results.find(r=>r.status==='rejected');assert.equal(failed?.status==='rejected'&&(failed.reason as any).code,'GIFT_CHALLENGE_EXPIRED');});
 assert.equal(f.calls.length,2);assert.equal(f.calls[1]!.options.idempotencyKey,key);assert.equal(f.calls[1]!.body.order_revision,'5');assert.equal(f.calls[1]!.body['Flint-Gift-Card-Challenge'],proof);assert.ok(f.calls.every(call=>call.options.authMode==='checkout'&&call.options.apiKey===undefined&&call.options.maxAttempts===1));assert.equal(row(f).status,'succeeded');
 for(const name of readdirSync(f.dir)){const bytes=readFileSync(join(f.dir,name));for(const secret of [code,proof,url])assert.equal(bytes.includes(Buffer.from(secret)),false);}
 assert.deepEqual(JSON.parse(row(f).result!),{order_id:f.order.order_id,order_revision:f.order.order_revision});
}));
test('I5 code binding refuses a changed code without any checkout read or gift call',async()=>use(async f=>{const view=await challenged(f);await retryRefused(f,view.challenge_id,'GIFT_CHALLENGE_CODE_CHANGED',false,'DIFFERENT-CODE');}));
for(const source of ['active','remembered'] as const)test(`I5 wrong code precedes the remote ${source} open attempt`,async()=>use(async f=>{const view=await challenged(f);openAttempt(f,source);await retryRefused(f,view.challenge_id,'GIFT_CHALLENGE_CODE_CHANGED',false,'DIFFERENT-CODE');}));
for(const state of ['closed','recovery','disabled','paid'] as const)test(`I5 wrong code precedes the remote ${state} gift fence`,async()=>use(async f=>{const view=await challenged(f);remoteGiftFence(f,state);await retryRefused(f,view.challenge_id,'GIFT_CHALLENGE_CODE_CHANGED',false,'DIFFERENT-CODE');}));
for(const status of ['pending','unknown'])test(`I5 local ${status} payment precedes wrong code`,async()=>use(async f=>{const view=await challenged(f);localPayment(f,status);await retryRefused(f,view.challenge_id,'PAYMENT_ATTEMPT_IN_PROGRESS',false,'DIFFERENT-CODE');}));
for(const source of ['active','remembered'] as const)test(`I17 correct code with the remote ${source} open attempt closes without applying`,async()=>use(async f=>{const view=await challenged(f);openAttempt(f,source);await retryRefused(f,view.challenge_id,'PAYMENT_ATTEMPT_IN_PROGRESS',true);}));
for(const state of ['closed','recovery','disabled','paid'] as const)test(`I17 correct code with the remote ${state} gift fence closes without applying`,async()=>use(async f=>{const view=await challenged(f);remoteGiftFence(f,state);await retryRefused(f,view.challenge_id,state==='closed'||state==='recovery'?'CHECKOUT_SESSION_NOT_OPEN':'GIFT_CARDS_NOT_EDITABLE',true);}));
for(const status of ['open','closed','retrying'] as const)test(`I6 changed session precedes ${status} and expiry with no Flint read`,async()=>use(async f=>{
 const view=await challenged(f);f.store.run('UPDATE gift_challenges SET status=?,expires_at=? WHERE challenge_id=?',status,Date.now()-1,view.challenge_id);f.store.run('UPDATE payment_checkouts SET checkout_session_id=? WHERE checkout_ref=?','cs_replaced',f.record.checkout_ref);const reads=f.reads.length;
 await assert.rejects(()=>f.retry(view.challenge_id),{code:'GIFT_CHALLENGE_SESSION_CHANGED'});assert.equal(f.reads.length,reads);assert.equal(f.calls.length,1);assert.equal(row(f).status,'challenge');assert.equal(f.store.get<{status:string}>('SELECT status FROM gift_challenges WHERE challenge_id=?',view.challenge_id)?.status,'closed');
}));
for(const status of ['closed','retrying','expired'] as const)test(`I6 same-session ${status} stays expired`,async()=>use(async f=>{const view=await challenged(f);if(status==='expired')f.store.run('UPDATE gift_challenges SET expires_at=? WHERE challenge_id=?',Date.now()-1,view.challenge_id);else f.store.run('UPDATE gift_challenges SET status=? WHERE challenge_id=?',status,view.challenge_id);const reads=f.reads.length;await assert.rejects(()=>f.retry(view.challenge_id),{code:'GIFT_CHALLENGE_EXPIRED'});assert.equal(f.reads.length,reads);assert.equal(f.calls.length,1);}));
