for(const source of ['active','remembered'] as const)test(`I7 remote ${source} open attempt precedes the changed order revision`,async()=>use(async f=>{const view=await challenged(f);f.order.order_revision='6';openAttempt(f,source);await retryRefused(f,view.challenge_id,'PAYMENT_ATTEMPT_IN_PROGRESS',true);}));
