 const view=await challenged(f),before=row(f);Object.assign(source==='order'?f.client.orders:f.client.checkoutSessions,{get:async(_id:string,_params:unknown,options:RequestOptions)=>{f.reads.push(options);throw refusal('UNKNOWN_FAILURE','',503);}});
