async function unknownGift(f:ReturnType<typeof fixture>){f.send(async()=>{throw refusal('UNKNOWN_FAILURE','',503);});await assert.rejects(()=>f.apply(),{code:'UNKNOWN_FAILURE'});return row(f);}
async function unknownHttpGift(h:Parameters<Parameters<typeof routeUse>[0]>[0]){h.send(async()=>{throw refusal('UNKNOWN_FAILURE','',503);});const response=await h.post(h.root+'/gift-card',{gift_card_code:code});assert.equal(response.status,503);return row(h);}
function installInvoiceLaunch(h:Parameters<Parameters<typeof routeUse>[0]>[0],send?:()=>void){
 Object.assign(h.client.me,{createInvoiceCheckoutSession:async()=>{send?.();return {checkout_session:{...h.session,order_id:h.order.order_id,surface:'embedded',page_origin:h.config.appOrigin},checkout_access:{checkout_auth_token:'fixture checkout authority'},reused_existing:false};}});
}
function appliedGift(f:ReturnType<typeof fixture>){f.order.order_revision='6';f.order.gift_cards=[{gift_card_id:'gift_fixture',last_characters:'TURE',available_money:{amount:'1000',currency:'USD'}}] as Order['gift_cards'];f.order.gift_card_estimate={can_pay:true,order_revision:'6',gift_card_money:{amount:'500',currency:'USD'},processor_money:{amount:'500',currency:'USD'},gift_cards:[{gift_card_id:'gift_fixture',amount_money:{amount:'500',currency:'USD'}}]} as Order['gift_card_estimate'];}
const giftActions=(f:ReturnType<typeof fixture>)=>f.store.all("SELECT * FROM actions WHERE kind IN ('gift_apply','gift_remove')");
function assertDeadline(value:number,now:number){assert.ok(value>=now+GIFT_SETTLE_MS-1000&&value<=Date.now()+GIFT_SETTLE_MS);}
function checkoutCredentials(options:RequestOptions){const credentials=options.credentials;assert.ok(credentials&&'CheckoutSessionIDHeader'in credentials);return credentials;}

