test('GR16 concurrent recovery requests send one replay and fence the waiter',async()=>use(async f=>{
 await unknownGift(f);let begin!:()=>void,release!:()=>void;const started=new Promise<void>(resolve=>{begin=resolve;}),held=new Promise<void>(resolve=>{release=resolve;});f.send(async()=>{begin();await held;appliedGift(f);return f.order;});const first=f.apply('recovery-one');await started;const second=f.apply('recovery-two');release();const results=await Promise.allSettled([first,second]);assert.equal(results[0].status,'fulfilled');assert.equal(results[1].status,'rejected');if(results[1].status==='rejected')assert.equal(results[1].reason.code,'ACTION_IN_PROGRESS');assert.equal(f.calls.length,2);assert.equal(giftActions(f).length,1);
}));
test('GR17 recovery ownership checks leave the victim action and apply limiter untouched',async()=>routeUse(async h=>{
 const original=await unknownHttpGift(h),owner=h.app.record(h.record.checkout_ref).user_id;h.store.run('UPDATE payment_checkouts SET user_id=? WHERE checkout_ref=?','victim_owner',h.record.checkout_ref);for(let count=0;count<11;count++)for(const path of [h.root+'/gift-card',h.root+'/gift-card/gift_fixture/remove'])assert.equal((await h.post(path,{gift_card_code:code})).status,404);assert.deepEqual(row(h),original);assert.equal(h.calls.length,1);h.store.run('UPDATE payment_checkouts SET user_id=? WHERE checkout_ref=?',owner,h.record.checkout_ref);
 for(let count=0;count<4;count++)assert.equal((await h.post(h.root+'/gift-card',{gift_card_code:'DIFFERENT-CODE'})).status,409);assert.equal((await h.post(h.root+'/gift-card',{gift_card_code:code})).status,429);assert.equal((await h.signedOutPost(h.root+'/gift-card',{gift_card_code:code})).status,401);
}));
test('GR18 every gift send observes its settle deadline already committed',async()=>use(async f=>{
 const seen:number[]=[];f.send(async()=>{const pending=f.app.unresolvedGift(f.record)!;assertDeadline(pending.retry_after,Date.now());seen.push(pending.retry_after);throw refusal('UNKNOWN_FAILURE','',503);});await assert.rejects(()=>f.apply());f.store.run('UPDATE actions SET retry_after=? WHERE action_id=?',Date.now()+100000,row(f).action_id);await assert.rejects(()=>f.apply('new-replay'));assert.equal(seen.length,2);
 f.send(async()=>{const pending=f.app.unresolvedGift(f.record)!;assertDeadline(pending.retry_after,Date.now());return f.order;});await f.apply('release-apply');f.order.gift_cards=[{gift_card_id:'gift_fixture'}] as Order['gift_cards'];Object.assign(f.client.orders,{removeGiftCard:async()=>{const pending=f.app.unresolvedGift(f.record)!;assert.equal(pending.kind,'gift_remove');assertDeadline(pending.retry_after,Date.now());throw refusal('UNKNOWN_FAILURE','',503);}});await assert.rejects(()=>f.remove('gift_fixture'));await assert.rejects(()=>f.app.removeGift(f.record.checkout_ref,'gift_fixture','fresh-removal'));assert.equal(f.store.all("SELECT * FROM actions WHERE kind='gift_remove'").length,1);
}));
test('GR18 challenge claim commits its settle deadline before sending proof',async()=>use(async f=>{
 const view=await challenged(f);f.store.run('UPDATE actions SET retry_after=0 WHERE action_id=?',row(f).action_id);f.send(async()=>{const pending=f.app.unresolvedGift(f.record)!;assert.equal(pending.status,'pending');assertDeadline(pending.retry_after,Date.now());return f.order;});await f.retry(view.challenge_id);assert.equal(f.calls.length,2);
}));
